const $=s=>root.querySelector(s);const PAGE=36;let query='',category='全部',page=0,selected=null;
const categories=['全部',...new Set(ICONS.map(i=>i.category))];const catRoot=$('.categories');for(const name of categories){const b=document.createElement('button');b.type='button';b.textContent=name;b.dataset.category=name;b.setAttribute('aria-pressed',String(name===category));b.addEventListener('click',()=>{category=name;page=0;render()});catRoot.appendChild(b)}
