function select(icon){selected=icon.name;$('.selection').hidden=false;$('#selected-title').textContent=icon.label;$('#selected-name').textContent=icon.name+' · duotone';$('#selected-overlap').textContent=icon.lucideRelated?'已有 Lucide 相关语义：'+icon.lucideRelated+'。这里是 Phosphor 的独立双色绘制。':icon.semanticStatus;$('#svg-code').value=icon.svg;$('#source-path').textContent=icon.sourcePath;$('#source-sha').textContent='SHA256: '+icon.sha256;$('#source-url').textContent=icon.sourceURL;$('#copy-status').textContent='';for(const b of root.querySelectorAll('.icon-card'))b.setAttribute('aria-pressed',String(b.dataset.name===selected))}
function render(){const data=filtered(),pages=Math.max(1,Math.ceil(data.length/PAGE));page=Math.min(page,pages-1);const grid=$('.icon-grid');grid.replaceChildren();for(const icon of data.slice(page*PAGE,(page+1)*PAGE)){const b=document.createElement('button');b.type='button';b.className='icon-card';b.dataset.name=icon.name;b.setAttribute('aria-label',icon.label+' · '+icon.name);b.setAttribute('aria-pressed',String(selected===icon.name));const shape=document.createElement('span');shape.className='shape';shape.innerHTML=icon.svg;shape.firstElementChild.setAttribute('aria-hidden','true');shape.firstElementChild.setAttribute('focusable','false');const label=document.createElement('span');label.className='glyph-label';label.textContent=icon.label;const en=document.createElement('span');en.className='glyph-name';en.textContent=icon.name;b.append(shape,label,en);b.addEventListener('click',()=>select(icon));grid.appendChild(b)}$('.empty').hidden=!!data.length;$('#result').textContent=data.length+' 个图形'+(category==='全部'?' · 全部精选':' · '+category);$('#page-label').textContent=(page+1)+' / '+pages;$('#previous').disabled=page===0;$('#next').disabled=page===pages-1;for(const b of catRoot.children)b.setAttribute('aria-pressed',String(b.dataset.category===category));root.dataset.page=String(page+1);root.dataset.resultCount=String(data.length);}
